namespace SoulboundLegends.Siege{public static class SiegeGenerationValidation{public static bool IsCompatible(SiegeGenerationRequest r,out string reason){if(r==null){reason="Null request";return false;}if(r.mainMapCount!=5||r.subMapsPerMainMap!=7||r.totalSubMaps!=35){reason="Siege requires 5x7=35 sub-maps";return false;}if(r.capturePoints||r.csRoundRules){reason="CS/capture rules disabled";return false;}if(!r.requireControlCore||!r.useDestruction){reason="Core and destruction required";return false;}if(!r.finalRoundAtOneOne||!r.finalRoundSimultaneousAttackDefense){reason="1-1 simultaneous final required";return false;}reason="Compatible";return true;}}
}
